function Mark({size=40,className=''}){return <svg className={className+' mark'} width={size} height={size} viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="vyntra-red" x2=".7" y2="1"><stop stop-color="#ff7a8c"/><stop offset=".45" stop-color="#de284a"/><stop offset="1" stop-color="#730d25"/></linearGradient></defs><path fill="url(#vyntra-red)" d="M3 9h17l12 25L44 9h17L32 57z"/><path fill="#ffbac7" opacity=".65" d="M3 9h17l3 6H10l22 42z"/><path fill="#f15d7a" d="M32 45 48 9h13L32 57z"/></svg>}
